                    {
                        localPluginContext.Trace($"Found date filter: {queryDate:yyyy-MM-dd}");
                        return queryDate;
                    }
                }
            }

            // Process child filters recursively
            if (filter.Filters != null)
            {
                foreach (var childFilter in filter.Filters)
                {
                    var result = ExtractDateFromQueryExpression(childFilter, localPluginContext);
                    if (result.HasValue)
                        return result;
                }
            }

            return null;
        }

